// Extract vendor names from Clay's technographics data, normalizing to lowercase for reliable matching

const data = $json.body;
const techList = Array.isArray(data.technographics) ? data.technographics : [];

const vendors = techList.map(t => (t.vendor || '').toLowerCase());

const headcountMatch = (data.headcount || '').match(/[\d,]+/);
const headcount = headcountMatch ? parseInt(headcountMatch[0].replace(/,/g, '')) : 0;

// Vendor detection for Microsoft/Google is done at the suite level (not individual products like Teams or Meet), since tech-stack detection tools typically list "Microsoft" or "Google Workspace" as a vendor rather than every individual product. This trades precision for practical signal.

const categories = {
  crm: vendors.some(v => ['salesforce', 'hubspot', 'pipedrive'].includes(v)),
  calendarEmail: vendors.some(v => ['microsoft', 'google workspace', 'google'].includes(v)),
  videoConferencing: vendors.some(v => ['zoom', 'microsoft', 'google workspace', 'google'].includes(v)),
  dialers: vendors.some(v => ['aircall', 'cloudcall', 'dialpad', 'kixie', 'justcall', 'ringover', 'cloudtalk', 'talkdesk', 'nextiva', 'vonage'].includes(v)),
  salesEngagement: vendors.some(v => ['salesloft', 'outreach'].includes(v)),
};

// CRM presence is weighted heavily - the CRM Concierge agent needs it to write data - but Coaching and call recording could still deliver value without one, so it's not treated as a hard gate.

const hasCRM = categories.crm;

// Confirmed against Demodesk's own comparison pages: they position for 100-5,000 employee teams, explicitly steering 500+ rep orgs toward Gong instead.

const headcountFits = headcount >= 200 && headcount <= 5000;

let score = 0;
if (hasCRM) {
  score += 2;
}
const additionalCategories = Object.values(categories).filter(Boolean).length - (hasCRM ? 1 : 0);
score += additionalCategories;
if (headcountFits) score += 1;

// Build sales-rep-facing talking points based on which integration categories are present
const talkingPoints = [];
if (categories.crm) talkingPoints.push("CRM detected — auto-write fields, save 5+ hrs/week");
if (categories.calendarEmail) talkingPoints.push("Calendar/email integration — auto-booking & follow-ups");
if (categories.videoConferencing) talkingPoints.push("Video conferencing — auto record/transcribe/coach");
if (categories.dialers) talkingPoints.push("Dialer detected — captures phone calls too");
if (categories.salesEngagement) talkingPoints.push("Sales engagement tool — active outbound, coaching-ready");
if (headcountFits) talkingPoints.push(`Headcount (${headcount}) — SMB/mid-market fit`);
else if (headcount > 5000) talkingPoints.push(`Headcount (${headcount}) is large — Demodesk may lose to Gong here if the org needs enterprise-scale revenue intelligence.`);

const battlecardAngle = talkingPoints.map(p => `• ${p}`).join('\n');

// Competitor detection is tracked separately from scoring — it's context for the rep, not a purchase-readiness signal, since contract timing and satisfaction can't be verified from tech-stack data alone

const usesGong = vendors.includes('gong');
const usesZoominfo = vendors.includes('zoominfo'); // proxy for Chorus, which is bundled under ZoomInfo
const usesFathom = vendors.includes('fathom');

let competitorNote = null;
if (usesGong) competitorNote = "Using Gong — lead with pricing (EUR 49 vs EUR 108+/user) and instant vs. 20-30 min delayed coaching.";
else if (usesZoominfo) competitorNote = "Using Chorus/ZoomInfo — lead with standalone value, no platform lock-in required.";
else if (usesFathom) competitorNote = "Using Fathom — lead with methodology-native coaching (MEDDIC/BANT/SPICED) vs. their single scorecard tier.";

return {
  json: {
    ...$json,
    icp_score: score,
    battlecard_angle: battlecardAngle,
    competitor_note: competitorNote
  }
};
